definition:
negotiate_alliance_interaction = {
	category = interaction_category_diplomacy
	ai_min_reply_days = 4
	ai_max_reply_days = 9
	icon = alliance

	send_name = negotiate_alliance_interaction

	interface_priority = 60
	desc = negotiate_alliance_interaction_desc

	greeting = positive
	notification_text = NEGOTIATE_ALLIANCE_NOTIFICATION

	is_available = {
		trigger_if = {
			limit = { is_ai = yes }
			is_at_war = no
		}
	}

	is_shown = {
		scope:puppet_or_actor ?= {
			OR = {
				highest_held_title_tier >= 2
				scope:actor = { is_ai = no }
			}
			is_ruler = yes
			#childhood friendship with hostage event, where they swear to be friends forever
			OR = {
				is_any_family_relation_or_spouse_trigger = { CHARACTER = scope:recipient }
				hostage_oath_of_friendship_trigger = yes
				#Parents/spouse were blood brothers
				has_opinion_modifier = {
					modifier = blood_brother_close_family_opinion
					target = scope:recipient
				}
				house ?= {
					house_head ?= scope:puppet_or_actor
					any_house_relation = {
						any_relation_house = {
							exists = house_head
							scope:recipient = house_head
						}
						has_house_relation_parameter = unlocks_house_head_negotiate_alliance
					}
				}
			}
		}
		scope:recipient = {
			this != scope:puppet_or_actor
			NOT = { is_allied_to = scope:puppet_or_actor }
			is_ruler = yes
		}
	}

	is_valid_showing_failures_only = {
		scope:recipient = {
			is_playable_character = yes
			is_imprisoned = no
			highest_held_title_tier < tier_hegemony
		}
		scope:puppet_or_actor ?= {
			is_playable_character = yes
			is_imprisoned = no
			NOT = {
				is_at_war_with = scope:recipient
			}
			highest_held_title_tier < tier_hegemony
			OR = {
				#Ruler has the defensive negotiations perk
				has_perk = defensive_negotiations_perk
				#Ruler is married to other ruler.
				is_spouse_of = scope:recipient
				#Ruler is relative of other ruler
				is_parent_of = scope:recipient
				is_grandparent_of = scope:recipient
				is_great_grandparent_of = scope:recipient
				is_child_of = scope:recipient
				is_grandchild_of = scope:recipient
				is_great_grandchild_of = scope:recipient
				is_uncle_or_aunt_of = scope:recipient
				is_nibling_of = scope:recipient
				is_sibling_of = scope:recipient
				#Parents/spouse were blood brothers
				has_opinion_modifier = {
					modifier = blood_brother_close_family_opinion
					target = scope:recipient
				}


				custom_description = {
					text = rulers_family_is_married_to_other_ruler_trigger
					subject = scope:recipient
					object = scope:puppet_or_actor
					#Ruler's child/parent/sibling/grandchild/grandparent/uncle/aunt/niece/nephew is married to other ruler.
					scope:recipient = {
						any_spouse = {
							OR = {
								is_close_family_of = scope:puppet_or_actor
								is_nibling_of = scope:puppet_or_actor
								is_uncle_or_aunt_of = scope:puppet_or_actor
							}
						}
					}
				}

				custom_description = {
					text = rulers_family_is_married_to_other_ruler_trigger
					subject = scope:puppet_or_actor
					object = scope:recipient
					#Other ruler's child/parent/sibling/grandchild/grandparent/uncle/aunt/niece/nephew is married to first ruler.
					any_spouse = {
						OR = {
							is_close_family_of = scope:recipient
							is_nibling_of = scope:recipient
							is_uncle_or_aunt_of = scope:recipient
						}
					}
				}

				custom_description = {
					text = rulers_child_parent_sibling_is_married_to_other_rulers_trigger
					subject = scope:recipient
					object = scope:puppet_or_actor
					# Ruler's child/parent/sibling is married to other ruler's child/parent/sibling.
					any_close_family_member = {
						OR = {
							is_parent_of = scope:puppet_or_actor
							is_child_of = scope:puppet_or_actor
							is_sibling_of = scope:puppet_or_actor
						}
						any_spouse = {
							OR = {
								is_parent_of = scope:recipient
								is_child_of = scope:recipient
								is_sibling_of = scope:recipient
							}
						}
					}
				}

				custom_description = {
					text = hostage_oath_of_friendship_trigger
					subject = scope:recipient
					object = scope:puppet_or_actor
					#childhood friendship with hostage event, where they swear to be friends forever
					hostage_oath_of_friendship_trigger = yes
				}

				custom_tooltip = {
					text = house_relation_alliance_trigger
					house ?= {
						house_head ?= scope:puppet_or_actor
						any_house_relation = {
							any_relation_house = {
								exists = house_head
								scope:recipient = house_head
							}
							has_house_relation_parameter = unlocks_house_head_negotiate_alliance
						}
					}
				}
			}
		}
		custom_description = {
			text = "has_already_rejected_renegotiation"
			subject = scope:recipient
			NOT = {
				scope:puppet_or_actor = {
					has_opinion_modifier = {
						modifier = refused_alliance_opinion
						target = scope:recipient
					}
				}
			}
		}
	}

	on_auto_accept = {
		scope:recipient = {
			trigger_event = char_interaction.0234
		}
	}

	#Use hook
	send_option = {
		is_valid = {
			scope:puppet_or_actor = {
				has_usable_hook = scope:recipient
			}
		}
		flag = hook
		localization = GENERIC_SPEND_A_HOOK
	}
	should_use_extra_icon = {
		scope:puppet_or_actor = { has_usable_hook = scope:recipient }
	}
	extra_icon = "gfx/interface/icons/character_interactions/hook_icon.dds"

	# Admin Gov can spend Influence to increase AI acceptance towards other same-realm admin characters
	send_option = {
		is_shown = {
			scope:puppet_or_actor = {
				government_has_flag = government_has_influence
			}
			scope:recipient = {
				top_liege = scope:puppet_or_actor.top_liege
				government_has_flag = government_has_influence
			}
		}
		is_valid = {
			scope:puppet_or_actor = {
				influence >= major_influence_value
			}
			custom_tooltip = {
				text = ALREADY_USING_HOOK
				NOT = { scope:hook = yes }
			}
		}
		flag = influence
		localization = SPEND_INFLUENCE
	}

	send_options_exclusive = no

	is_highlighted = {
		scope:recipient = {
			this != scope:puppet_or_actor
			NOT = { is_allied_to = scope:puppet_or_actor }
			is_ruler = yes
		}
		scope:puppet_or_actor = {
			is_ruler = yes
			OR = {
				scope:actor = { is_ai = no }
				highest_held_title_tier >= 2
			}
			has_opinion_modifier = {
				modifier = blood_brother_close_family_opinion
				target = scope:recipient
			}
		}
	}

	on_accept = {
		scope:puppet_or_actor = {
			trigger_event = char_interaction.0235

			stress_and_fulfillment_impact = {
				shy = minor_stress_impact_gain
			}

			if = {
				limit = {
					scope:hook = yes
					has_usable_hook = scope:recipient
				}
				use_hook = scope:recipient
			}
			if = {
				limit = {
					scope:influence = yes
				}
				change_influence = major_influence_loss
			}
		}

		scope:recipient = {
			custom_tooltip = negotiate_alliance_effect_recipient_tooltip
		}

		#Set up alliance, depending on relation between rulers.
		hidden_effect = {
			#Prioritize marriage between rulers and/or direct blood relation between rulers first.
			if = {
				limit = {
					scope:puppet_or_actor = {
						OR = {
							is_spouse_of = scope:recipient
							is_child_of = scope:recipient
							is_parent_of = scope:recipient
							is_sibling_of = scope:recipient
							is_grandparent_of = scope:recipient
							is_great_grandparent_of = scope:recipient
							is_grandchild_of = scope:recipient
							is_great_grandchild_of = scope:recipient
							is_uncle_or_aunt_of = scope:recipient
							is_nibling_of = scope:recipient
						}
					}
				}
				scope:puppet_or_actor = {
					create_alliance = {
						target = scope:recipient
						allied_through_owner = scope:puppet_or_actor
						allied_through_target = scope:recipient
					}
				}
			}
			#...Then marriage between close family members and either actor or recipient.
			else_if = {
				limit = {
					scope:recipient = {
						any_spouse = {
							OR = {
								is_close_family_of = scope:puppet_or_actor
								is_nibling_of = scope:puppet_or_actor
								is_uncle_or_aunt_of = scope:puppet_or_actor
							}
						}
					}
				}
				scope:recipient = {
					random_spouse = {
						limit = {
							OR = {
								is_close_family_of = scope:puppet_or_actor
								is_nibling_of = scope:puppet_or_actor
								is_uncle_or_aunt_of = scope:puppet_or_actor
							}
						}
						save_scope_as = recipient_spouse
					}
				}
				scope:puppet_or_actor = {
					create_alliance = {
						target = scope:recipient
						allied_through_owner = scope:recipient_spouse
						allied_through_target = scope:recipient
					}
				}
			}
			else_if = {
				limit = {
					scope:puppet_or_actor = {
						any_spouse = {
							OR = {
								is_close_family_of = scope:recipient
								is_nibling_of = scope:recipient
								is_uncle_or_aunt_of = scope:recipient
							}
						}
					}
				}
				scope:puppet_or_actor = {
					random_spouse = {
						limit = {
							OR = {
								is_close_family_of = scope:recipient
								is_nibling_of = scope:recipient
								is_uncle_or_aunt_of = scope:recipient
							}
						}
						save_scope_as = actor_spouse
					}
				}
				scope:puppet_or_actor = {
					create_alliance = {
						target = scope:recipient
						allied_through_owner = scope:puppet_or_actor
						allied_through_target = scope:actor_spouse
					}
				}
			}
			#...And finally marriage between close relatives and close relatives.
			else_if = {
				limit = {
					scope:puppet_or_actor = {
						any_close_family_member = {
							OR = {
								is_child_of = scope:puppet_or_actor
								is_parent_of = scope:puppet_or_actor
								is_sibling_of = scope:puppet_or_actor
							}
							any_spouse = {
								OR = {
									is_child_of = scope:recipient
									is_parent_of = scope:recipient
									is_sibling_of = scope:recipient
								}
							}
						}
					}
				}
				scope:puppet_or_actor = {
					random_close_family_member = {
						limit = {
							OR = {
								is_child_of = scope:puppet_or_actor
								is_parent_of = scope:puppet_or_actor
								is_sibling_of = scope:puppet_or_actor
							}
							any_spouse = {
								OR = {
									is_child_of = scope:recipient
									is_parent_of = scope:recipient
									is_sibling_of = scope:recipient
								}
							}
						}
						save_scope_as = actor_spouse
						random_spouse = {
							limit = {
								OR = {
									is_child_of = scope:recipient
									is_parent_of = scope:recipient
									is_sibling_of = scope:recipient
								}
							}
							save_scope_as = recipient_spouse
						}
					}
				}
				scope:puppet_or_actor = {
					create_alliance = {
						target = scope:recipient
						allied_through_owner = scope:actor_spouse
						allied_through_target = scope:recipient_spouse
					}
				}
			}
			else_if = {
				limit = {
					scope:puppet_or_actor = { has_perk = defensive_negotiations_perk }
				}
				scope:puppet_or_actor = {
					create_alliance = {
						target = scope:recipient
						allied_through_owner = scope:puppet_or_actor
						allied_through_target = scope:recipient
					}
				}
				scope:recipient = { # This opinion modifier controls the interaction, and is removed when breaking the alliance in any way (though on_actions)
					add_opinion = {
						modifier = perk_negotiated_alliance_opinion
						target = scope:puppet_or_actor
					}
				}
			}
			else_if = {
				limit = {
					scope:puppet_or_actor = {
						hostage_oath_of_friendship_trigger = yes
					}
				}
				scope:puppet_or_actor = {
					create_alliance = {
						target = scope:recipient
						allied_through_owner = scope:puppet_or_actor
						allied_through_target = scope:recipient
					}
				}
			}
		}

		add_clan_unity_interaction_effect = {
			CHARACTER = scope:puppet_or_actor
			TARGET = scope:recipient
			VALUE = minor_unity_gain
			DESC = clan_unity_alliance.desc
			REVERSE_NON_HOUSE_TARGET = no
		}
	}

	on_decline = {
		scope:puppet_or_actor = {
			trigger_event = char_interaction.0236
		}
		scope:puppet_or_actor = {
			add_opinion = {
				modifier = refused_alliance_opinion
				target = scope:recipient
			}
		}

		add_clan_unity_interaction_effect = {
			CHARACTER = scope:puppet_or_actor
			TARGET = scope:recipient
			VALUE = minor_unity_loss
			DESC = clan_unity_alliance_refusal.desc
			REVERSE_NON_HOUSE_TARGET = no
		}
	}

	auto_accept = {
		custom_description = {
			text = "spending_hook"
			subject = scope:puppet_or_actor
			object = scope:recipient
			scope:hook = yes
		}
	}
	ai_accept = {
		base = 0

		negotiate_alliance_interaction_ai_acceptance = yes

		# Tier Difference 	(+/-)
		# Inheritance 		(+)
		# Opinion 			(+/-)
		# Dynasty Prestige. (+)
		# Different Faith.	(-)
		# Liege is asking 	(+)
		# Dread 			(+)
		# Power difference 	(+/-)
		# Claimants (+/-)
		# Same House (+)
		# Declared war opinion
		# Actor is at war penalty

		modifier = {
			add = 20
			scope:recipient = {
				is_close_family_of = scope:puppet_or_actor
			}
			desc = CLOSE_FAMILY_REASON
		}

		modifier = {
			add = 10
			scope:recipient = {
				NOT = { is_close_family_of = scope:puppet_or_actor }
				is_extended_family_of = scope:puppet_or_actor
			}
			desc = EXTENDED_FAMILY_REASON
		}

		modifier = {
			add = -20
			scope:recipient = {
				NOT = { is_close_or_extended_family_of = scope:puppet_or_actor }
				any_spouse = {
					NOT = { is_close_family_of = scope:puppet_or_actor }
					is_extended_family_of = scope:puppet_or_actor
				}
			}
			desc = DISTANT_FAMILY_CONNECTION_REASON
		}

		modifier = {
			scope:recipient = {
				has_relation_lover = scope:puppet_or_actor
			}
			add = {
				value = 25
			}
			desc = WE_ARE_LOVERS
		}
		modifier = {
			scope:recipient = {
				has_relation_friend = scope:puppet_or_actor
			}
			add = {
				value = 25
			}
			desc = WE_ARE_FRIENDS
		}
		modifier = {
			scope:recipient = {
				is_heir_of = scope:puppet_or_actor
			}
			scope:puppet_or_actor = {
				tier_difference = {
					target = scope:recipient
					value > 0
				}
			}
			add = {
				value = 10
				if = {
					limit = {
						scope:puppet_or_actor = { player_heir = scope:recipient }
					}
					add = 10
				}
			}
			desc = IS_HEIR_REASON
		}
		modifier = {
			add = 20
			desc = FAMILY_BLOOD_BROTHERHOOD_REASON
			scope:puppet_or_actor = {
				has_opinion_modifier = {
					modifier = blood_brother_close_family_opinion
					target = scope:recipient
				}
			}
		}

		# Unity modifiers
		evaluate_action_increasing_house_unity = {
			VALUE = 100
		}

		fp3_struggle_resist_allied_wars_modifier = yes

		# LOW LEGITIMACY
		modifier = {
			desc = "LOW_LEGITIMACY_REASON"
			scope:puppet_or_actor = {
				OR = {
					has_legitimacy_flag = reduced_alliance_acceptance
					has_legitimacy_flag = very_reduced_alliance_acceptance
					has_legitimacy_flag = massively_reduced_alliance_acceptance
				}
			}
			add = {
				value = 0
				if = {
					limit = { scope:puppet_or_actor = { has_legitimacy_flag = reduced_alliance_acceptance } }
					add = -25
				}
				if = {
					limit = { scope:puppet_or_actor = { has_legitimacy_flag = very_reduced_alliance_acceptance } }
					add = -50
				}
				if = {
					limit = { scope:puppet_or_actor = { has_legitimacy_flag = massively_reduced_alliance_acceptance } }
					add = -100
				}
			}
		}

		# HIGH LEGITIMACY
		modifier = {
			desc = "HIGH_LEGITIMACY_REASON"
			scope:puppet_or_actor = {
				OR = {
					has_legitimacy_flag = increased_alliance_acceptance
					has_legitimacy_flag = very_increased_alliance_acceptance
					has_legitimacy_flag = extra_increased_alliance_acceptance
				}
			}
			add = {
				value = 0
				if = {
					limit = { scope:puppet_or_actor = { has_legitimacy_flag = increased_alliance_acceptance } }
					add = 10
				}
				if = {
					limit = { scope:puppet_or_actor = { has_legitimacy_flag = very_increased_alliance_acceptance } }
					add = 25
				}
				if = {
					limit = { scope:puppet_or_actor = { has_legitimacy_flag = extra_increased_alliance_acceptance } }
					add = 50
				}
			}
		}

		# TGP ALLIANCE WITH NF HOUSE HEAD
		modifier = {
			add = 750
			scope:puppet_or_actor = {
				is_house_head = yes
				scope:recipient.house ?= this.house
				any_held_title = { is_noble_family_title = yes }
			}
			desc = JAPANESE_HOUSE_HEAD_ALLIANCE_REASON
		}

		modifier = {
			add = 10
			desc = pam_praised_hunting_alliance_accept_reason
			scope:recipient = {
				exists = var:pam_praised_hunting_alliance_var
				var:pam_praised_hunting_alliance_var = scope:puppet_or_actor
			}
		}
	}

	ai_targets = {
		ai_recipients = dynasty
		max = 20
	}

	ai_targets = {
		ai_recipients = family
		max = 10
	}

	ai_targets = {
		ai_recipients = spouses
	}
	ai_frequency_by_tier = {
		barony = 0
		county = 144
		duchy = 72
		kingdom = 36
		empire = 36
		hegemony = 36
	}

	ai_will_do = {
		base = 0

		modifier = {
			add = 100
			any_ally = {
				count < 2
			}
			scope:recipient = { # Don't propose alliances to tiny insignificant rulers just because
				OR = {
					current_military_strength >= scope:puppet_or_actor.eighty_percent_of_current_military_strength
					primary_title.tier >= scope:puppet_or_actor.primary_title.tier
					AND = {
						primary_title.tier >= tier_duchy
						scope:puppet_or_actor.primary_title.tier < tier_empire
					}
				}
			}
		}

		modifier = { # Clans always want alliances with Vassals
			add = 100
			scope:puppet_or_actor = {
				government_has_flag = government_is_clan
			}
			scope:recipient = {
				is_vassal_of = scope:puppet_or_actor
			}
		}

		# Unity modifiers
		evaluate_action_increasing_house_unity = {
			VALUE = 100
		}

		modifier = { # The AI shouldn't propose to their Lieges
			factor = 0
			is_liege_or_above_of = scope:recipient
		}

		modifier = { # The AI shouldn't propose to their Vassals unless Clan
			factor = 0
			scope:puppet_or_actor = {
				NOT = { government_has_flag = government_is_clan }
			}
			scope:recipient = {
				is_vassal_of = scope:puppet_or_actor
			}
		}
	}
}

on_accept:
on_accept = {
	scope:puppet_or_actor = {
		trigger_event = char_interaction.0235

		stress_and_fulfillment_impact = {
			shy = minor_stress_impact_gain
		}

		if = {
			limit = {
				scope:hook = yes
				has_usable_hook = scope:recipient
			}
			use_hook = scope:recipient
		}
		if = {
			limit = {
				scope:influence = yes
			}
			change_influence = major_influence_loss
		}
	}

	scope:recipient = {
		custom_tooltip = negotiate_alliance_effect_recipient_tooltip
	}

	#Set up alliance, depending on relation between rulers.
	hidden_effect = {
		#Prioritize marriage between rulers and/or direct blood relation between rulers first.
		if = {
			limit = {
				scope:puppet_or_actor = {
					OR = {
						is_spouse_of = scope:recipient
						is_child_of = scope:recipient
						is_parent_of = scope:recipient
						is_sibling_of = scope:recipient
